1. package tofu
2. 
3. import (
4. 	"fmt"
5. 	"os"
6. 
7. 	plugin_exec "github.com/thegeeklab/wp-plugin-go/v4/exec"
8. 	"github.com/urfave/cli/v2"
9. )
10. 
11. const TofuBin = "/usr/local/bin/tofu"
12. 
13. type Tofu struct {
14. 	InitOptions InitOptions
15. 	FmtOptions  FmtOptions
16. 
17. 	OutFile     string
18. 	Parallelism int
19. 	Targets     cli.StringSlice
20. 	Refresh     bool
21. 	NoLog       bool
22. }
23. 
24. // InitOptions include options for the OpenTofu init command.
25. type InitOptions struct {
26. 	Backend       *bool    `json:"backend"`
27. 	BackendConfig []string `json:"backend-config"`
28. 	Lock          *bool    `json:"lock"`
29. 	LockTimeout   string   `json:"lock-timeout"`
30. 	Lockfile      string   `json:"lockfile"`
31. }
32. 
33. // FmtOptions fmt options for the OpenTofu fmt command.
34. type FmtOptions struct {
35. 	List  *bool `json:"list"`
36. 	Write *bool `json:"write"`
37. 	Diff  *bool `json:"diff"`
38. 	Check *bool `json:"check"`
39. }
40. 
41. func (t *Tofu) Version() *plugin_exec.Cmd {
42. 	cmd := plugin_exec.Command(TofuBin, "version")
43. 
44. 	if !t.NoLog {
45. 		cmd.Stdout = os.Stdout
46. 		cmd.Stderr = os.Stderr
47. 	}
48. 
49. 	return cmd
50. }
51. 
52. func (t *Tofu) Init() *plugin_exec.Cmd {
53. 	args := []string{
54. 		"init",
55. 	}
56. 
57. 	if t.InitOptions.Backend != nil {
58. 		args = append(args, fmt.Sprintf("-backend=%t", *t.InitOptions.Backend))
59. 	}
60. 
61. 	for _, v := range t.InitOptions.BackendConfig {
62. 		args = append(args, fmt.Sprintf("-backend-config=%s", v))
63. 	}
64. 
65. 	if t.InitOptions.Lock != nil {
66. 		args = append(args, fmt.Sprintf("-lock=%t", *t.InitOptions.Lock))
67. 	}
68. 
69. 	if t.InitOptions.Lockfile != "" {
70. 		args = append(args, fmt.Sprintf("-lockfile=%s", t.InitOptions.Lockfile))
71. 	}
72. 
73. 	if t.InitOptions.LockTimeout != "" {
74. 		args = append(args, fmt.Sprintf("-lock-timeout=%s", t.InitOptions.LockTimeout))
75. 	}
76. 
77. 	// Fail tofu execution on prompt
78. 	args = append(args, "-input=false")
